import{_ as n,o as t,c as i,ah as r}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Update: Gernot Blümel und der fliegende Laptop","description":"Wir integrieren die Laptop-Affäre und den Kinderwagen-Spaziergang in das Projekt. Über die Kunst, im richtigen Moment alles zu vergessen.","frontmatter":{"title":"Update: Gernot Blümel und der fliegende Laptop","description":"Wir integrieren die Laptop-Affäre und den Kinderwagen-Spaziergang in das Projekt. Über die Kunst, im richtigen Moment alles zu vergessen.","date":"2026-02-28T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-28-bluemel-laptop-integration.md","filePath":"logbuch/2026-02-28-bluemel-laptop-integration.md"}'),a={name:"logbuch/2026-02-28-bluemel-laptop-integration.md"};function l(o,e,s,d,p,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="update-gernot-blumel-und-der-fliegende-laptop" tabindex="-1">Update: Gernot Blümel und der fliegende Laptop <a class="header-anchor" href="#update-gernot-blumel-und-der-fliegende-laptop" aria-label="Permalink to &quot;Update: Gernot Blümel und der fliegende Laptop&quot;">​</a></h1><p>Die Sektion „Gerichtliche Nachspiele“ hat ein neues Highlight: <strong>Gernot Blümel</strong>. Sein Kinderwagen-Spaziergang während einer Hausdurchsuchung ist so grotesk, dass man ihn in einer Mockumentary kaum erfinden müsste.</p><p><strong>Warum Blümel perfekt in unser Ensemble passt:</strong></p><ul><li><strong>Der Kinderwagen als Datenträger:</strong> Dieses visuelle Motiv ist satirisches Gold. Es symbolisiert die Unschuld, hinter der die harte Machtpolitik ihre Spuren versteckt.</li><li><strong>Die 80 Gedächtnislücken:</strong> Wir nutzen diese „Amnesie-Performance“ als rhythmische Vorlage für einen Dialog in Teil 4.</li><li><strong>Die Laptop-Leugnung:</strong> „Ich habe keinen Laptop“ wird in unserem Film zum modernen Mantra des Schweigens.</li></ul><p>Wir haben Blümel bereits eine Szene gewidmet, in der er versucht, seinem Kleinkind den Pointillismus zu erklären – während die WKStA an der Tür läutet.</p><p><em>Dokumentiert von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',6)])])}const h=n(a,[["render",l]]);export{m as __pageData,h as default};
